const sheetData = $json.values;
if (!sheetData || sheetData.length < 2) return [];

const headers = sheetData[0];
const results = [];

for (let i = 1; i < sheetData.length; i++) {
  const row = sheetData[i];
  if (!row || row.length === 0) continue;
  const obj = {};
  headers.forEach((header, idx) => {
    obj[header] = row[idx] !== undefined ? row[idx] : '';
  });
  results.push({ json: obj });
}

return results;

const MAPA_EMAILS = {
  'Rodrigo Bertolini': 'rodrigo.bertolini@fazcapital.com.br',
  'Lucas Boeira':      'lucas.boeira@fazcapital.com.br',
  'Allini Pianca':     'allini.pianca@fazcapital.com.br',
  'Athos Baruk':       'athos.baruk@fazcapital.com.br',
  'Fabio Borges':      'fabio.borges@fazcapital.com.br'
};

// Remove acentos e normaliza para comparacao robusta
function norm(s) {
  return (s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
}

// Match exato ou parcial ("Athos" -> "Athos Baruk")
function findEmail(nome) {
  if (!nome) return '';
  if (MAPA_EMAILS[nome]) return MAPA_EMAILS[nome];
  const nomeLower = nome.toLowerCase();
  for (const [chave, email] of Object.entries(MAPA_EMAILS)) {
    const chaveLower = chave.toLowerCase();
    if (chaveLower.includes(nomeLower)) return email;
    if (chave.split(' ').some(p => p.toLowerCase() === nomeLower)) return email;
  }
  return '';
}

const items = $input.all();
const results = [];

for (const item of items) {
  const d = item.json;

  // Debug: loga todos os campos recebidos
  console.log('--- ITEM ---');
  console.log('Status:', JSON.stringify(d['Status']));
  console.log('Ultimo Status Enviado:', JSON.stringify(d['Ultimo Status Enviado']));
  console.log('Responsavel:', JSON.stringify(d['Responsável'] || d['Responsavel']));
  console.log('Thread ID:', JSON.stringify(d['Thread ID']));

  const status = (d['Status'] || '').trim();
  const sNorm  = norm(status);
  const uNorm  = norm(d['Ultimo Status Enviado']);

  if (sNorm === '') {
    console.log('SKIP: Status vazio');
    continue;
  }
  if (sNorm === 'aberto') {
    console.log('SKIP: Status e Aberto');
    continue;
  }
  if (sNorm === uNorm) {
    console.log('SKIP: Status igual ao ultimo enviado (pos-normalizacao):', sNorm);
    continue;
  }

  // Le Responsavel com e sem acento
  const responsavel = (d['Responsável'] || d['Responsavel'] || '').split('|')[0].trim();
  const emailDest   = findEmail(responsavel);

  if (!emailDest) {
    console.log('SKIP: Responsavel nao encontrado no mapa:', JSON.stringify(responsavel));
    continue;
  }

  const idCaso   = d['ID Caso']          || '';
  const cliente  = d['Código Cliente']   || d['Codigo_Cliente'] || '';
  const assunto  = d['Assunto']           || '';
  const proto    = d['Protocolo N1']      || '';
  const threadId = d['Thread ID']         || '';

  const subjectLine = 'Re: [SUBIR BV] ' + idCaso + ' | Cliente ' + cliente + ' | ' + assunto;

  let corpo = '';

  if (sNorm.includes('analise')) {
    corpo =
      'Prezado(a),\n\n' +
      '🔍 Atualização de Status!\n\n' +
      'O caso abaixo está Em Análise pela nossa equipe.\n\n' +
      'ID: ' + idCaso + '\n' +
      'Status: ' + status + '\n\n' +
      '📌 Protocolo: ' + proto + '\n' +
      '👤 Cliente: ' + cliente + '\n\n' +
      '📝 Assunto Caso: ' + assunto + '\n\n' +
      'Estamos trabalhando na resolução e em breve traremos novidades.\n' +
      'Caso possua novas informações, responda este e-mail.\n\n\nAtenciosamente,\n\n';

  } else if (sNorm === 'resolvido') {
    corpo =
      'Prezado(a),\n\n' +
      '✅ Caso Resolvido!\n\n' +
      'O caso abaixo foi resolvido pela nossa equipe.\n\n' +
      'ID: ' + idCaso + '\n' +
      'Status: ' + status + '\n\n' +
      '📌 Protocolo: ' + proto + '\n' +
      '👤 Cliente: ' + cliente + '\n\n' +
      '📝 Assunto Caso: ' + assunto + '\n\n' +
      'Esperamos ter atendido às suas expectativas.\n' +
      'Caso o problema persista, responda este e-mail para reabrir o caso.\n\n\nAtenciosamente,\n\n';

  } else if (sNorm.includes('aguard')) {
    corpo =
      'Prezado(a),\n\n' +
      '⏳ Aguardando seu Retorno!\n\n' +
      'O caso abaixo está aguardando informações da sua parte.\n\n' +
      'ID: ' + idCaso + '\n' +
      'Status: ' + status + '\n\n' +
      '📌 Protocolo: ' + proto + '\n' +
      '👤 Cliente: ' + cliente + '\n\n' +
      '📝 Assunto Caso: ' + assunto + '\n\n' +
      'Por favor, responda este e-mail com as informações solicitadas para prosseguirmos.\n\n\nAtenciosamente,\n\n';

  } else {
    // Fallback: qualquer outro status
    corpo =
      'Prezado(a),\n\n' +
      '🔄 Atualização de Status!\n\n' +
      'O status do caso abaixo foi atualizado.\n\n' +
      'ID: ' + idCaso + '\n' +
      'Status: ' + status + '\n\n' +
      '📌 Protocolo: ' + proto + '\n' +
      '👤 Cliente: ' + cliente + '\n\n' +
      '📝 Assunto Caso: ' + assunto + '\n\n' +
      'Atenciosamente,\n\n';
  }

  console.log('OK: Montando e-mail para', emailDest, '| Status:', status);

  results.push({
    json: {
      ...d,
      corpo_email: corpo,
      email_destinatario: emailDest,
      assunto_email: subjectLine,
      request_body: {
        message: {
          subject: subjectLine,
          body: { contentType: 'Text', content: corpo },
          toRecipients: [{ emailAddress: { address: emailDest } }],
          ccRecipients:  [{ emailAddress: { address: 'lucas.boeira@fazcapital.com.br' } }],
          internetMessageHeaders: [
            { name: 'In-Reply-To', value: threadId },
            { name: 'References',  value: threadId }
          ]
        }
      }
    }
  });
}

return results;
